PAGE = dict(
    slug='y_ticks',
    title='Pane::y_ticks',
    signature='Pane& Pane::y_ticks(Series positions, RangeView::Of<std::string_view> labels)\nPane& Pane::y_ticks(Series positions, std::initializer_list<std::string_view> labels)\nPane& Pane::clear_y_ticks() noexcept',
    intro='Replaces the automatic ticks of the y axis with ticks you choose: a position for each tick and the text drawn beside it. Positions are in the data units of the axis and need not be sorted; labels are drawn as written, so they can be words, dates or formatted numbers. The ticks are stored in `y_axis().ticks`, and the format of the numbers ([`y_tick_format`](y_tick_format.md), [`y_auto_tick_decimals`](y_auto_tick_decimals.md)) does not apply to them. A tick whose position lies outside the displayed range is not drawn, so a manual range ([`y_limits`](y_limits.md)) decides which of the ticks appear.\n\nThere are three call forms: a braced list of labels, a range of string views, and a `Series` of positions; positions given as a plain numeric vector are converted. `clear_y_ticks()` removes the explicit ticks and restores the automatic ones, exactly. A call is refused with `pluss::Error`, leaving the previous ticks as they were, when the positions are empty or are not a vector, or when the number of labels differs from the number of positions.',
    parameters='**positions** (`Series` or numeric vector)\n    Where the ticks go, in data units. A non-empty vector.\n\n**labels** (`RangeView::Of<std::string_view>` or braced list)\n    The text of each tick; as many as there are positions.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='labels', text='Explicit labels at chosen positions. Three ticks are placed at 1, 2 and 3 with words for labels; the automatic ticks of this axis are replaced by them.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto fig = studio("y_ticks_labels");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{1, 2, 3, 4});\npane.x_tick_labels(false);\npane.z_tick_labels(false);\nstd::cout << "automatic: " << texts(fig.to_svg()) << "\\n";\npane.y_ticks(std::vector<double>{1, 2, 3}, {"low", "mid", "high"});\nstd::cout << "explicit:  " << texts(fig.to_svg()) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='labels_from_strings', text='Labels from a list of strings. A `std::vector<std::string_view>` of labels works as well as the braced list, and the positions can be any numeric vector.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto fig = studio("y_ticks_strings");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{1, 2, 3, 4});\npane.x_tick_labels(false);\npane.z_tick_labels(false);\nconst std::vector<std::string_view> names = {"Q1", "Q2", "Q3", "Q4"};\nstd::vector<double> positions;\nfor (std::size_t i = 0; i < names.size(); ++i) positions.push_back(1.0 + static_cast<double>(i));\npane.y_ticks(positions, pluss::msharp::RangeView::Of<std::string_view>(names));\nstd::cout << texts(fig.to_svg()) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='series', text="Positions as a `Series`. The positions can be passed as a Series, which is what the library's numeric results are; the labels are drawn in order of the positions given.",
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto fig = studio("y_ticks_series");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{1, 2, 3, 4});\npane.x_tick_labels(false);\npane.z_tick_labels(false);\nauto positions = pluss::make_series(std::vector<double>{1.0, 4.0}, {2});\npane.y_ticks(positions, std::vector<std::string_view>{"first", "last"});\nstd::cout << texts(fig.to_svg()) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='outside', text='Only ticks inside the range are drawn. The tick at 10 lies outside the axis range and the tick at 0 is below it, so only the middle one is shown; widening the range with `limits` brings them in.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto build = [&](bool wide) {\n  auto fig = studio("y_ticks_outside");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{1, 2, 3, 4});\n  pane.x_tick_labels(false);\n  pane.z_tick_labels(false);\n  pane.y_ticks(std::vector<double>{0, 2, 10}, {"zero", "two", "ten"});\n  if (wide) pane.y_limits(Range1d{0.0, 10.0});\n  return fig.to_svg();\n};\nstd::cout << "automatic range: " << texts(build(false)) << "\\n";\nstd::cout << "range 0 to 10:   " << texts(build(true)) << "\\n";\nauto fig = studio("y_ticks_outside_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{1, 2, 3, 4});\npane.y_ticks(std::vector<double>{0, 2, 10}, {"zero", "two", "ten"});\npane.y_limits(Range1d{0.0, 10.0});\nfig.save_svg("figure.svg");'),
        dict(id='clear', text='Clearing. `clear_y_ticks()` removes the explicit ticks and the automatic ones come back; the figure equals the one that never set any.',
             code='auto build = [&](bool set_then_clear) {\n  auto fig = studio("y_ticks_clear");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  if (set_then_clear) pane.y_ticks(std::vector<double>{1, 2}, {"a", "b"}).clear_y_ticks();\n  return fig.to_svg();\n};\nstd::cout << "equal: " << (build(true) == build(false)) << "\\n";\nauto fig = studio("y_ticks_clear_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nfig.save_svg("figure.svg");'),
        dict(id='invalid', text='Invalid specifications are refused and the previous ticks are kept. Empty positions, positions and labels of different lengths, and positions that are not a vector each throw `pluss::Error`.',
             code='auto fig = studio("y_ticks_invalid");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_ticks(std::vector<double>{1, 2}, {"a", "b"});\nauto attempt = [&](const char* label, auto call) {\n  try {\n    call();\n  } catch (const pluss::Error& e) {\n    std::cout << label << ": " << e.message() << "\\n";\n  }\n};\nattempt("no positions", [&] { pane.y_ticks(std::vector<double>{}, {}); });\nattempt("length mismatch", [&] { pane.y_ticks(std::vector<double>{1, 2}, {"only one"}); });\nattempt("not a vector", [&] { pane.y_ticks(pluss::make_series(std::vector<double>{1, 2, 3, 4}, {2, 2}), {"a", "b"}); });\nstd::cout << "kept: " << pane.y_axis().ticks->labels.size() << " labels\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- `y_ticks` throws, so it is not `noexcept`; `clear_y_ticks` never throws.\n- For labels at the integers 1, 2, 3, ... use [`y_categories`](y_categories.md), which builds the positions for you.',
    see=['[`Pane::y_categories`](y_categories.md): labels at evenly spaced positions.', '[`Pane::y_tick_labels`](y_tick_labels.md): hide the tick labels.', '[`Pane::y_limits`](y_limits.md): the range that decides which ticks show.', '[`Pane::x_ticks`](x_ticks.md): the same setting for the x axis.', '[`Pane::z_ticks`](z_ticks.md): the same setting for the z axis.'],
)
